const embedding = $input.item.json.data[0].embedding;

const webhook = $('Webhook').item.json.body;

const nivelesPermitidos = {
  basico: ["BASICO"],
  intermedio: ["BASICO", "INTERMEDIO"],
  avanzado: ["BASICO", "INTERMEDIO", "AVANZADO"]
};

const niveles = nivelesPermitidos[webhook.nivel.toLowerCase()] ?? ["BASICO"];

return {
  json: {
    vector: embedding,
    pregunta: webhook.pregunta,
    limit: 5,
    score_threshold: 0.35,
    with_payload: true,
    filter: {
      must: [
        {
          key: "dificultad",
          match: {
            any: niveles
          }
        }
      ]
    }
  }
};

const puntos = $json.result?.points ?? [];

return {
  json: {
    pregunta: $('preparar consulta').item.json.pregunta,
    cursos: puntos.map(punto => ({
      id_curso: punto.payload.id_curso,
      nombre: punto.payload.nombre,
      descripcion: punto.payload.descripcion,
      categoria: punto.payload.categoria,
      dificultad: punto.payload.dificultad,
      duracion: punto.payload.duracion,
      score: punto.score
    }))
  }
};

const body = $json.body ?? {};

const pregunta = body.pregunta;
const nivel = body.nivel;

const respuesta = {
  valida: true,
  motivo: null,
  pregunta: null,
  nivel: null
};

// 1. Validar pregunta

if (typeof pregunta !== 'string' || pregunta.trim() === '') {
  respuesta.valida = false;
  respuesta.motivo = 'La pregunta es obligatoria.';
  return { json: respuesta };
}

// 2. Limitar longitud

if (pregunta.length > 1000) {
  respuesta.valida = false;
  respuesta.motivo = 'La pregunta es demasiado larga.';
  return { json: respuesta };
}

// 3. Limitar cantidad de líneas

const lineas = pregunta.split(/\r?\n/).length;

if (lineas > 20) {
  respuesta.valida = false;
  respuesta.motivo = 'La consulta tiene un formato no válido.';
  return { json: respuesta };
}

// 4. Normalizar y validar nivel

const nivelNormalizado = typeof nivel === 'string'
  ? nivel.trim().toUpperCase()
  : '';

const nivelesValidos = [
  'BASICO',
  'INTERMEDIO',
  'AVANZADO',
  'NULL'
];

if (!nivelesValidos.includes(nivelNormalizado)) {
  respuesta.valida = false;
  respuesta.motivo = 'El nivel debe ser BASICO, INTERMEDIO o AVANZADO.';
  return { json: respuesta };
}

// 5. Detectar intentos de manipular las instrucciones

const patronesBloqueados = [

  // Ignorar o cambiar instrucciones
  /ignora\s+(todas\s+)?las\s+instrucciones/i,
  /ignora\s+(las\s+)?instrucciones\s+(anteriores|previas|del\s+sistema)/i,
  /olvida\s+(todas\s+)?las\s+instrucciones/i,
  /olvida\s+(las\s+)?instrucciones\s+(anteriores|previas)/i,
  /descarta\s+(todas\s+)?las\s+instrucciones/i,
  /no\s+sigas\s+(las\s+)?instrucciones/i,
  /deja\s+de\s+seguir\s+(las\s+)?instrucciones/i,
  /cambia\s+(tus|las)\s+instrucciones/i,
  /modifica\s+(tus|las)\s+instrucciones/i,

  // Prompt del sistema
  /system\s*prompt/i,
  /systemprompt/i,
  /prompt\s+del\s+sistema/i,
  /prompt\s+interno/i,
  /prompt\s+oculto/i,
  /prompt\s+privado/i,
  /instrucciones\s+internas/i,
  /instrucciones\s+del\s+sistema/i,
  /reglas\s+internas/i,
  /reglas\s+del\s+sistema/i,
  /mensaje\s+del\s+sistema/i,
  /configuraci[oó]n\s+interna/i,

  // Solicitar el prompt
  /mu[eé]strame\s+(el\s+)?prompt/i,
  /muestra\s+(el\s+)?prompt/i,
  /ens[eé]ñame\s+(el\s+)?prompt/i,
  /dime\s+(el\s+)?prompt/i,
  /revela\s+(el\s+)?prompt/i,
  /revel[aá]\s+(tus\s+)?instrucciones/i,
  /cu[aá]les\s+son\s+tus\s+instrucciones/i,
  /qu[eé]\s+instrucciones\s+recibiste/i,
  /qu[eé]\s+reglas\s+tienes/i,

  // Credenciales
  /dame\s+(las\s+)?credenciales/i,
  /mu[eé]strame\s+(las\s+)?credenciales/i,
  /credenciales\s+(de|del|para)/i,
  /api\s*key/i,
  /api\s*token/i,
  /access\s*token/i,
  /secret\s*key/i,
  /client\s*secret/i,
  /private\s*key/i,
  /clave\s+(secreta|privada|de\s+api)/i,
  /contrase[ñn]a\s+(de|del|para)/i,
  /password\s+(de|del|para)/i,
  /secreto\s+(de|del|para)/i,

  // Información interna
  /configuraci[oó]n\s+(de|del)\s+(sistema|servidor|backend)/i,
  /datos\s+internos/i,
  /informaci[oó]n\s+interna/i,
  /estructura\s+interna/i,
  /arquitectura\s+interna/i,
  /endpoint\s+interno/i,
  /url\s+interna/i,
  /direcci[oó]n\s+ip/i,
  /ip\s+del\s+servidor/i,
  /puerto\s+del\s+servidor/i,

  // Acceso a bases de datos
  /mu[eé]strame\s+(la\s+)?base\s+de\s+datos/i,
  /dame\s+(la\s+)?base\s+de\s+datos/i,
  /consulta\s+(la\s+)?base\s+de\s+datos/i,
  /accede\s+(a\s+)?mysql/i,
  /accede\s+(a\s+)?qdrant/i,
  /mu[eé]strame\s+(las\s+)?tablas/i,
  /mu[eé]strame\s+(los\s+)?registros/i,
  /lista\s+(las\s+)?tablas/i,
  /ejecuta\s+(una\s+)?consulta\s+sql/i,
  /ejecuta\s+sql/i,
  /select\s+\*.*from/i,

  // Cambiar el comportamiento del modelo
  /modo\s+administrador/i,
  /modo\s+admin/i,
  /modo\s+desarrollador/i,
  /developer\s+mode/i,
  /modo\s+sin\s+restricciones/i,
  /sin\s+restricciones/i,
  /sin\s+filtros/i,
  /jailbreak/i,
  /dan\s+mode/i,

  // Cambiar el rol del modelo
  /ahora\s+eres\s+(un|una)/i,
  /a\s+partir\s+de\s+ahora\s+eres/i,
  /act[uú]a\s+como\s+(un|una)/i,
  /simula\s+ser\s+(un|una)/i,
  /tu\s+nuevo\s+rol\s+es/i,
  /cambia\s+tu\s+rol/i,
  /ignora\s+tu\s+rol/i,

  // Solicitar instrucciones completas
  /repite\s+(tus\s+)?instrucciones/i,
  /copia\s+(tus\s+)?instrucciones/i,
  /imprime\s+(tus\s+)?instrucciones/i,
  /escribe\s+(tus\s+)?instrucciones/i,
/muestra\s+todo\s+lo\s+que\s+sabes\s+sobre\s+tu\s+configuraci[oó]n/i
];

for (const patron of patronesBloqueados) {
  if (patron.test(pregunta)) {
    respuesta.valida = false;
    respuesta.motivo = 'La consulta contiene una solicitud no permitida.';
    return { json: respuesta };
  }
}

// 6. Detectar estructuras de prompts

const patronesPrompt = [
  /system\s*:/i,
  /developer\s*:/i,
  /assistant\s*:/i,
  /user\s*:/i,
  /instructions\s*:/i,
  /context\s*:/i,
  /task\s*:/i,
  /role\s*:/i,
  /objective\s*:/i,
  /prompt\s*:/i,

  /<system[\s>]/i,
  /<\/system>/i,
  /<developer[\s>]/i,
  /<\/developer>/i,
  /<assistant[\s>]/i,
  /<\/assistant>/i,
  /<instructions?[\s>]/i,
  /<\/instructions?>/i,

  /\[\s*system\s*\]/i,
  /\[\s*developer\s*\]/i,
  /\[\s*assistant\s*\]/i,

  /\{\s*"role"\s*:/i
];

for (const patron of patronesPrompt) {
  if (patron.test(pregunta)) {
    respuesta.valida = false;
    respuesta.motivo = 'La consulta contiene una estructura no permitida.';
    return { json: respuesta };
  }
}

// 7. Consulta válida

respuesta.pregunta = pregunta.trim();
respuesta.nivel = nivelNormalizado;

return { json: respuesta };

