const recomendacion = $('Registrar recomendación').first().json;
const cursos = $('formatear resultados').first().json.cursos ?? [];

return cursos.map(curso => ({
  json: {
    idRecomendacion: recomendacion.idRecomendacion,
    idCurso: curso.id_curso,
    similitud: curso.score
  }
}));

const error = $json.error ?? {};

const mensajeTecnico =
  error.message ??
  error.description ??
  "No se proporcionaron detalles.";

let titulo = "No se pudo generar el embedding";
let mensaje = "Ocurrió un problema al convertir la consulta en un vector para realizar la búsqueda semántica.";
let accion = "Inténtalo nuevamente. Si el problema continúa, contacta al administrador.";

const textoError = mensajeTecnico.toLowerCase();

if (
  textoError.includes("econnrefused") ||
  textoError.includes("connection refused") ||
  textoError.includes("connect") ||
  textoError.includes("connection") ||
  textoError.includes("network")
) {
  titulo = "No se pudo conectar con el servicio de embeddings";
  mensaje = "No fue posible establecer la conexión con el servicio utilizado para generar el embedding de la consulta.";
  accion = "Verifica que el servicio de embeddings esté disponible e inténtalo nuevamente.";
}

else if (
  textoError.includes("enotfound") ||
  textoError.includes("getaddrinfo") ||
  textoError.includes("dns") ||
  textoError.includes("host not found")
) {
  titulo = "No se pudo encontrar el servicio de embeddings";
  mensaje = "El sistema no pudo localizar el servicio utilizado para generar el embedding.";
  accion = "Verifica la dirección del servicio y la configuración de conexión.";
}

else if (
  textoError.includes("401") ||
  textoError.includes("unauthorized") ||
  textoError.includes("invalid api key") ||
  textoError.includes("authentication")
) {
  titulo = "No se pudo autenticar con el servicio de embeddings";
  mensaje = "El sistema no pudo autenticarse correctamente con el proveedor de embeddings.";
  accion = "Verifica la credencial configurada para acceder al servicio.";
}

else if (
  textoError.includes("403") ||
  textoError.includes("forbidden") ||
  textoError.includes("permission")
) {
  titulo = "No hay permisos para generar embeddings";
  mensaje = "El servicio rechazó la solicitud porque la credencial utilizada no tiene permisos suficientes.";
  accion = "Verifica los permisos y la configuración de acceso del proveedor.";
}

else if (
  textoError.includes("404") ||
  textoError.includes("not found") ||
  textoError.includes("model not found") ||
  textoError.includes("model does not exist")
) {
  titulo = "No se encontró el modelo de embeddings";
  mensaje = "El modelo configurado para generar embeddings no está disponible.";
  accion = "Verifica el nombre del modelo y que esté disponible en el proveedor configurado.";
}

else if (
  textoError.includes("400") ||
  textoError.includes("bad request") ||
  textoError.includes("invalid request") ||
  textoError.includes("invalid input") ||
  textoError.includes("invalid model") ||
  textoError.includes("input")
) {
  titulo = "La solicitud de embedding no es válida";
  mensaje = "El servicio rechazó los datos enviados para generar el embedding.";
  accion = "Verifica la pregunta enviada y la configuración del modelo de embeddings.";
}

else if (
  textoError.includes("429") ||
  textoError.includes("rate limit") ||
  textoError.includes("too many requests") ||
  textoError.includes("quota") ||
  textoError.includes("insufficient")
) {
  titulo = "Se alcanzó el límite del servicio de embeddings";
  mensaje = "El proveedor de embeddings rechazó temporalmente la solicitud debido a un límite de uso.";
  accion = "Espera unos minutos antes de intentarlo nuevamente o verifica los límites de la cuenta.";
}

else if (
  textoError.includes("500") ||
  textoError.includes("502") ||
  textoError.includes("503") ||
  textoError.includes("504") ||
  textoError.includes("internal server error") ||
  textoError.includes("bad gateway") ||
  textoError.includes("service unavailable")
) {
  titulo = "El servicio de embeddings no está disponible";
  mensaje = "El proveedor de embeddings encontró un problema al procesar la solicitud.";
  accion = "Espera unos minutos e inténtalo nuevamente.";
}

else if (
  textoError.includes("timeout") ||
  textoError.includes("timed out") ||
  textoError.includes("etimedout")
) {
  titulo = "El servicio de embeddings tardó demasiado en responder";
  mensaje = "El servicio no respondió dentro del tiempo esperado al generar el embedding.";
  accion = "Espera unos minutos e inténtalo nuevamente.";
}

return [
  {
    json: {
      estado: "error",
      titulo,
      mensaje,
      accion_recomendada: accion,
      puede_reintentar: true,
      error_tecnico: mensajeTecnico
    }
